<script>
document.querySelectorAll('[data-gallery-orientation-select]').forEach(select=>{const source=select.closest('form').querySelector('[data-gallery-source-select]');function update(){const portrait=select.value==='portrait';for(const option of source.options)option.disabled=portrait&&option.value!=='admin';if(portrait)source.value='admin';}select.addEventListener('change',update);update();});
</script>
